def dedupe_contacts(rows):
    """
    Deduplicate CRM contact rows according to the CPR data rules.

    rows: list of dicts with string fields first_name, last_name, email, phone,
          zip, tags, opted_out, updated.
    Returns a list of merged dicts (same keys), one per person, ordered by each
    person's earliest row in the input.
    """
    DIGITS = "0123456789"
    FIELDS = ["first_name", "last_name", "email", "phone",
              "zip", "tags", "opted_out", "updated"]

    def get(row, key):
        val = row.get(key, "")
        return val if isinstance(val, str) else ("" if val is None else str(val))

    # Rule 1: normalize email
    def norm_email(raw):
        e = raw.strip().lower()
        if e.count("@") == 1:
            local, domain = e.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.split("+", 1)[0].replace(".", "")
                e = local + "@gmail.com"
        return e

    # Rule 2: email validity
    def email_is_valid(e):
        if e.count("@") != 1:
            return False
        local, domain = e.split("@")
        return (bool(local)
                and "." in domain
                and not domain.startswith(".")
                and not domain.endswith("."))

    # Rule 3: normalize phone; returns "" if invalid
    def norm_phone(raw):
        d = "".join(c for c in raw if c in DIGITS)
        if len(d) == 11 and d[0] == "1":
            d = d[1:]
        return d if len(d) == 10 else ""

    # Precompute normalized values and apply rule 4 (drop unusable rows)
    kept = []  # list of (input_index, info dict)
    for idx, row in enumerate(rows):
        e = norm_email(get(row, "email"))
        email = e if email_is_valid(e) else ""
        phone = norm_phone(get(row, "phone"))
        if not email and not phone:
            continue
        kept.append((idx, {
            "row": row,
            "email": email,
            "phone": phone,
            "last_key": get(row, "last_name").strip().lower(),
            "updated": get(row, "updated").strip(),
        }))

    # Union-find over positions in `kept`
    parent = list(range(len(kept)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            # Keep the smaller (earlier) position as root; not required but tidy
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    # Rule 5: match on email, or on (phone, non-empty last name)
    by_email = {}
    by_phone_last = {}
    for pos, (_, info) in enumerate(kept):
        if info["email"]:
            if info["email"] in by_email:
                union(pos, by_email[info["email"]])
            else:
                by_email[info["email"]] = pos
        if info["phone"] and info["last_key"]:
            key = (info["phone"], info["last_key"])
            if key in by_phone_last:
                union(pos, by_phone_last[key])
            else:
                by_phone_last[key] = pos

    # Group members; dict insertion order gives rule 7 ordering
    # (groups appear in order of their earliest kept row).
    groups = {}
    for pos in range(len(kept)):
        groups.setdefault(find(pos), []).append(pos)

    def pick_latest(members, value_fn):
        """Value from the most recently updated member where value_fn is
        non-empty; ties go to the earlier row (members are in input order)."""
        best_val, best_upd = "", None
        for pos in members:
            val = value_fn(kept[pos][1])
            if not val:
                continue
            upd = kept[pos][1]["updated"]
            if best_upd is None or upd > best_upd:
                best_val, best_upd = val, upd
        return best_val

    result = []
    for members in groups.values():
        merged = {}
        for field in ("first_name", "last_name", "zip"):
            merged[field] = pick_latest(
                members, lambda info, f=field: get(info["row"], f).strip())
        merged["email"] = pick_latest(members, lambda info: info["email"])
        merged["phone"] = pick_latest(members, lambda info: info["phone"])

        tags = set()
        for pos in members:
            for t in get(kept[pos][1]["row"], "tags").split(";"):
                t = t.strip().lower()
                if t:
                    tags.add(t)
        merged["tags"] = ";".join(sorted(tags))

        merged["opted_out"] = "Y" if any(
            get(kept[pos][1]["row"], "opted_out").strip().upper() == "Y"
            for pos in members) else "N"

        merged["updated"] = max(kept[pos][1]["updated"] for pos in members)

        result.append({k: merged[k] for k in FIELDS})

    return result
```

A few notes before you send tomorrow:

- **The function doesn't remove opted-out people.** It marks a merged person `opted_out = "Y"` if any of their rows opted out, but they stay in the output. Filter them out before sending:
  ```python
  send_list = [p for p in dedupe_contacts(rows)
               if p["opted_out"] == "N" and p["email"]]
  ```
  The `p["email"]` check also matters. People kept only because of a valid phone number will have no email address.
- **Opt-outs only carry over when rows match.** If someone opted out under one address and is subscribed under a different one, and there's no phone and last name match connecting them, they'll still get the email. The rules can't catch that.
- **Gmail normalization changes the address you send to.** For example, `Jane.Doe+news@googlemail.com` becomes `janedoe@gmail.com`. Gmail delivers both to the same inbox, so this should be fine, but your email platform will show the normalized address rather than what's stored in the CRM.
- **Dates are compared as strings.** This is correct for zero-padded ISO dates like `2026-10-02`. If some `updated` values have timestamps or a different format, normalize them first.
- I stripped whitespace from `opted_out` before checking it, so `" y"` counts as an opt-out. That's slightly more lenient than the written rule, and safer.

I'd recommend running it on a sample of the export and spot-checking a few merged groups before the send.
